diff --git a/tests/auth.test.js b/tests/auth.test.js
new file mode 100644
index 0000000..8c26330
--- /dev/null
+++ b/tests/auth.test.js
@@ -0,0 +1,83 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { createApp } from "../src/http/server.js";
+import { openStore } from "../src/db/store.js";
+import { fresh, NOW, seed } from "./helpers.js";
+
+const headers = (role) => ({ Authorization: `Bearer seed-${role}` });
+
+test("all routes require a known bearer key in the usual error shape", async () => {
+  const handle = createApp(fresh());
+  for (const authorization of [undefined, "Bearer unknown", "Basic seed-manager", "Bearer", "Bearer seed-manager extra"]) {
+    const response = await handle({ path: "/items", headers: { authorization } });
+    assert.equal(response.status, 401);
+    assert.equal(response.body.error.code, "unauthorized");
+    assert.equal(typeof response.body.error.message, "string");
+  }
+  assert.equal((await handle({ path: "/nope" })).status, 401);
+});
+
+test("roles allow reads and limit every write route", async () => {
+  const writes = [
+    ["POST", "/recipes/1/cook", true],
+    ["POST", "/batches/1/waste", true],
+    ["POST", "/temperatures", true],
+    ["POST", "/stocktakes/1/counts", true],
+    ["POST", "/stocktakes", false],
+    ["POST", "/stocktakes/1/finish", false],
+    ["PUT", "/items/1/allergens", false],
+    ["POST", "/orders", false],
+    ["POST", "/orders/3/send", false],
+    ["POST", "/orders/3/cancel", false],
+    ["POST", "/orders/2/receive", false],
+    ["POST", "/prices", false],
+    ["POST", "/dishes", false],
+    ["POST", "/outbox/1/sent", false],
+    ["POST", "/import/items", false],
+    ["POST", "/jobs/nightly", false],
+  ];
+  for (const role of ["viewer", "cook", "manager"]) {
+    const handle = createApp(fresh());
+    assert.equal((await handle({ path: "/items", headers: headers(role) })).status, 200);
+    assert.equal((await handle({ path: "/audit", headers: headers(role) })).status, role === "manager" ? 200 : 403);
+    for (const [method, path, cookAllowed] of writes) {
+      const store = fresh();
+      const before = JSON.stringify(store.data);
+      const response = await createApp(store)({ method, path, headers: headers(role), body: {} });
+      const allowed = role === "manager" || (role === "cook" && cookAllowed);
+      assert.equal(response.status === 403, !allowed, `${role}: ${method} ${path}`);
+      if (!allowed) {
+        assert.equal(response.body.error.code, "forbidden");
+        assert.equal(JSON.stringify(store.data), before);
+      }
+    }
+  }
+});
+
+test("audit persists with changes, lists newest first and never contains secrets", async () => {
+  const file = join(mkdtempSync(join(tmpdir(), "larder-audit-")), "db.json");
+  writeFileSync(file, JSON.stringify(seed()));
+  const store = openStore(file);
+  let saves = 0;
+  const save = store.save.bind(store);
+  store.save = () => { saves++; save(); };
+  const handle = createApp(store, { clock: () => NOW });
+  const request = { method: "POST", path: "/temperatures", headers: headers("cook"), body: { location: "fridge", celsius: 3 } };
+  assert.equal((await handle(request)).status, 201);
+  assert.equal((await handle({ ...request, path: "/temperatures?shift=pm" })).status, 201);
+  assert.equal(saves, 2);
+  const expected = {
+    time: new Date(NOW).toISOString(), name: "Seed cook", method: "POST", path: "/temperatures?shift=pm", status: 201,
+  };
+  const response = await handle({ path: "/audit", headers: headers("manager") });
+  assert.deepEqual(response.body[0], expected);
+  assert.equal(response.body[1].path, "/temperatures");
+  assert.equal(JSON.stringify(response.body).includes("seed-cook"), false);
+  assert.deepEqual(openStore(file).data.audit, store.data.audit);
+  assert.equal(JSON.parse(readFileSync(file)).temperatures.length, seed().temperatures.length + 2);
+  await handle({ ...request, body: {} });
+  assert.equal(store.data.audit.length, 2);
+});
